	"penTest.title": "Test del pulsante della penna",
	"penTest.intro": "Tocca l'area qui sotto con la penna tenendo premuto il pulsante laterale: una volta con un tocco rapido e una volta trascinando, poi una volta senza pulsante. In Obsidian per Android l'app vede il pulsante solo mentre la punta tocca (il passaggio a penna sospesa non viene inoltrato, quindi premerlo in aria non mostra nulla). Il registro mostra cosa riceve l'app e cosa ne ricava. Non viene disegnato né salvato nulla.",
	"penTest.air": "Samsung: se premendo il pulsante si apre il menu Air command, il sistema si tiene il pulsante mentre la penna è sospesa e l'app non lo riceve. Disattiva Air command in Impostazioni > Funzioni avanzate > S Pen (controlla anche Air actions e Note rapide; nome e posizione possono cambiare con la versione di One UI), poi riprova.",
