	"redact.button": "Oscura…",
	"redact.apply": "Applica i riquadri",
	"redact.note.on": "L'inchiostro viene tagliato al riquadro, e una casella di testo, un'immagine, un'equazione o una nota che tocca un riquadro viene tolta per intero. Gli estratti delle pagine di questo quaderno vengono esclusi finché ha almeno un riquadro (la loro immagine salvata può mostrare ciò che hai coperto). Un PDF o un'immagine dietro la pagina diventa un'immagine piatta con il riquadro incorporato: il suo testo non si può più selezionare né cercare. Gli stessi riquadri coprono le altre esportazioni di questo quaderno su questo dispositivo (consegna, condivisione, immagini, Markdown) finché non li disattivi. Il quaderno non viene mai modificato.",
