	"redact.nopages": "Questo quaderno non ha pagine.",
	"redact.unreadable": "Non è stato possibile leggere i riquadri di oscuramento di questo quaderno su questo dispositivo, quindi non è stato scritto nulla. Non si possono recuperare: apri Esporta… › Oscura…, disegna di nuovo i riquadri e premi Fatto (Fatto salva esattamente i riquadri che vedi, nessuno se non ne disegni), oppure azzera lì l'archivio dell'oscuramento.",
	"redact.unreadable.dialog": "Non è stato possibile leggere i riquadri salvati per questo quaderno su questo dispositivo e non si possono recuperare. Le esportazioni sono rifiutate finché non apri Oscura…, disegni di nuovo i riquadri e premi Fatto: Fatto salva esattamente i riquadri che vedi lì, nessuno se non ne disegni. Se chiudi senza Fatto non viene salvato nulla.",
	"redact.storeDamaged": "Non è stato possibile leggere alcuni riquadri di oscuramento salvati su questo dispositivo. È stata messa da parte una copia di ciò che c'era, e le esportazioni dei quaderni interessati sono rifiutate finché non ne disegni di nuovo i riquadri in Esporta… › Oscura… e premi Fatto, oppure azzeri lì l'archivio dell'oscuramento.",
	"redact.storeLost": "I riquadri di oscuramento salvati su questo dispositivo sono spariti e non è stato possibile conservarne nulla. Le esportazioni di ogni quaderno sono rifiutate finché non ne disegni di nuovo i riquadri in Esporta… › Oscura… e premi Fatto, oppure azzeri lì l'archivio dell'oscuramento.",
