	"help.redact.reset": "Compare quando non è stato possibile leggere i riquadri salvati. Elimina i riquadri di tutti i quaderni su questo dispositivo (dopo una conferma), così le esportazioni non sono più rifiutate.",
	"redact.offHint": "I riquadri di oscuramento sono disattivati per questa esportazione.",
