	"redact.full": "Troppi quaderni hanno i riquadri di oscuramento attivi per salvare anche questo su questo dispositivo. I suoi riquadri coprono comunque le sue esportazioni finché Obsidian non viene chiuso; disattivali in un altro quaderno per fare spazio.",
